# retention.py — อายุการเก็บอ่านจากบันทึกกิจกรรมการประมวลผลที่เดียว
#   ropa.yaml: customer_contact { purpose, lawful_basis, keep_days, stores[] }
#   stores[] คือบัญชีปลายทางทุกที่ที่ข้อมูลชุดนี้ไปอยู่ ต้องแก้พร้อม schema

def run_retention(spec, today):
    cutoff = today - timedelta(days=spec["keep_days"])
    erased = {}
    for store in spec["stores"]:
        erased[store.name] = store.erase_older_than(cutoff)
    erasure_log.write(purpose=spec["purpose"], basis=spec["lawful_basis"],
                      cutoff=cutoff, erased_per_store=erased)
    return erased
